from pathlib import Path
import json,hashlib
root=Path(__file__).resolve().parent
raw=(root/'tokens.json').read_bytes();t=json.loads(raw)
out=['/* Generated by export_web.py from tokens.json v'+str(t['version'])+'; sha256 '+hashlib.sha256(json.dumps(t,sort_keys=True,separators=(',',':'),ensure_ascii=False).encode('utf-8')).hexdigest()+'. Do not edit by hand. */',':root {']
for x in t['color']['tokens']:out.append('  --ds-color-'+x['name']+': '+x['value']['light']+';')
for x in t['spacing']['tokens']:out.append('  --ds-'+x['name']+': '+x['value']+';')
for x in t['radius']['tokens']:out.append('  --ds-'+x['name']+': '+x['value']+';')
out.append('  --ds-font-web: '+t['type']['families']['app']+';')
for g in t['type']['groups']:
 if g['name'].startswith('Web'):
  for x in g['styles']:
   for k,suffix in [('fontSize','size'),('lineHeight','line'),('fontWeight','weight'),('letterSpacing','tracking')]:out.append('  --ds-'+x['name']+'-'+suffix+': '+str(x[k])+';')
out += ['  --ds-primary: var(--ds-color-blue);','  --ds-accent: var(--ds-color-blue);','  --ds-accent-text: var(--ds-color-blue-strong);','  --ds-accent-soft: var(--ds-color-blue-soft);','  --ds-shadow-overlay: '+t['shadow']['tokens'][0]['value']['light']+';','}']
out.append('[data-ds-theme="dark"] {')
for x in t['color']['tokens']:out.append('  --ds-color-'+x['name']+': '+x['value']['dark']+';')
out += ['  --ds-shadow-overlay: '+t['shadow']['tokens'][0]['value']['dark']+';','}']
for name in ['spacious','compact']:
 p=t['webProfiles'][name];l=p['layout'];c=p['components']
 values={'page-gutter':48 if name=='spacious' else l['desktopPagePaddingX'],'section-gap':l['desktopBlockGap'] if name=='spacious' else l['groupGap'],'panel-padding':l['desktopSmallCardPadding'] if name=='spacious' else l['panelPadding'],'panel-gap':l['panelGapDesktop'],'row-height':c['listRowMinHeight'] if name=='spacious' else c['tableRowDefaultMinHeight'],'control-height':c['buttonHeight'] if name=='spacious' else c['primaryButtonHeight']}
 out.append('[data-ds-profile="'+name+'"] {')
 for k,v in values.items():out.append('  --ds-'+k+': '+str(v)+'px;')
 out.append('}')
p=t['products']['0xhieu-xyz'];v=p['valuation'];w=p['work'];cv=p['cv']
out += ['[data-ds-product="0xhieu-xyz"] {','  --ds-primary: var(--ds-color-ink);','  --ds-accent: '+p['palette']['accent']+';','  --ds-accent-text: var(--ds-color-orange-text);','  --ds-accent-soft: var(--ds-color-yellow-soft);']
for k,value in {'val-header-height':v['headerHeight'],'val-header-font-size':v['headerFontDesktop'],'val-header-line-height':v['headerLineDesktop'],'val-panel-height':v['panelHeight'],'val-row-height':v['rowHeight'],'val-metric-row-height':v['metricRowMinHeight'],'val-panel-gap':v['panelGapDesktop'],'work-project-column':w['projectColumnDesktop'],'work-phase-column':w['phaseColumn'],'work-group-gap':w['groupGap'],'work-safe-bottom':w['floatingToolbarSafeBottom'],'cv-hero-top':cv['heroPaddingTopDesktop'],'cv-section-gap':cv['sectionGapDesktop'],'cv-portrait':cv['portraitDesktop']}.items():out.append('  --ds-'+k+': '+str(value)+'px;')
for key in ['frameMaxWidth','cardRadius','cardPaddingX','sectionPaddingY','cardGap']:
 import re
 name=re.sub(r'(?<!^)(?=[A-Z])','-',key).lower()
 out.append('  --ds-workspace-'+name+': '+str(p['workspace'][key])+'px;')
out.append('  --ds-workspace-header-surface: var(--ds-color-ground);')
for key,name in [('cardRadius','card-radius'),('controlRadius','control-radius'),('badgeRadius','badge-radius')]:
 out.append('  --ds-product-'+name+': '+str(p['sharedComponents'][key])+'px;')
out.append('}')
out += ['@media (max-width: 640px) {','  [data-ds-profile] { --ds-page-gutter: 16px; }','  [data-ds-profile="spacious"] { --ds-section-gap: 32px; --ds-panel-padding: 16px; --ds-panel-gap: 16px; }','  [data-ds-product="0xhieu-xyz"] { --ds-val-header-font-size: '+str(v['headerFontMobile'])+'px; --ds-val-header-line-height: '+str(v['headerLineMobile'])+'px; --ds-val-panel-gap: '+str(v['panelGapMobile'])+'px; --ds-cv-hero-top: '+str(cv['heroPaddingTopMobile'])+'px; --ds-cv-section-gap: '+str(cv['sectionGapMobile'])+'px; --ds-cv-portrait: '+str(cv['portraitMobile'])+'px; }','}']
(root/'web.css').write_text('\n'.join(out)+'\n',encoding='utf-8')
print('Exported web.css from tokens v'+str(t['version']))
